// This fixed heap has row0[18]=1, row1[18]=0 and no discarded high carry.
// Thus signed19(row0)+signed19(row1) is the exact eight-term sum. Both
// zero rows also encode zero for dot8's disabled high half. The emitted
// arithmetic verifier must establish these stronger representation facts.
private val rowWords = for {
  half <- 0 until (if (dot16Enabled) 2 else 1)
  row <- 0 until 2
} yield pRows(half)(row).asSInt.pad(storedResultBits)
require(rowWords.forall(_.getWidth == storedResultBits), "signed rows share the exact sum width")
// Fixed-width additions are associative modulo 2^19/2^20. The true final
// eight/sixteen-term result fits that signed width, so reconstruction is exact.
private val compressedSum = rowWords.reduce(_ + _)
require(compressedSum.getWidth == storedResultBits, "exact fixed-width carry-save finish")

